CC_MID = "Quick word: if you want to keep today's verses and read along every day, it's all free in Community Covenant, at covenant dot crispus mundo dot com."
def JOIN(q, tom):
    return (f"So here's my question for you. {q} Tell me in the comments. To join Community Covenant, go to covenant dot crispus mundo dot com, "
            f"tap Create Account, choose your daily focus, and add it to your home screen. Tomorrow is {tom} Invite two people to read with us. See you tomorrow in the Word.")
def INTRO(d, rng):
    return (f"Welcome to Cover to Cover. Day {d} of three hundred sixty-five. Today is {rng}, read from the King James Version, with not one word changed. "
            "This reading comes to you from Community Covenant, the free daily Bible and prayer app. The link is in the post.")
